// Code node "Validate email" (02 email to sheet). Run once for all items.
//
// The webhook receives an inbound-parse JSON (the shape Postmark, Mailgun or SendGrid post).
// The Message-ID is the idempotency key, normalised so "<ABC@x>" and "abc@x" are the same
// message. An HTML-only message is reduced to text.
const WEBHOOK_NODE = 'Webhook';
const MAX_TEXT = 100000;

const body = ($(WEBHOOK_NODE).first().json || {}).body;

function fail(reason) {
  return [{ json: { valid: false, reason } }];
}

function address(value) {
  const raw = typeof value === 'string' ? value.trim() : '';
  const angled = raw.match(/^(.*)<([^<>\s]+)>$/);
  const email = (angled ? angled[2] : raw).trim().toLowerCase();
  const name = angled ? angled[1].trim().replace(/^"|"$/g, '') : '';
  return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email) ? { email, name } : null;
}

function htmlToText(html) {
  return html
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .trim();
}

if (!body || typeof body !== 'object' || Array.isArray(body)) return fail('body must be a JSON object');
const messageId =
  typeof body.message_id === 'string' ? body.message_id.trim().replace(/^<|>$/g, '').toLowerCase() : '';
if (!/^[^\s<>]{3,250}$/.test(messageId) || !messageId.includes('@')) {
  return fail('message_id is missing or malformed');
}
const from = address(body.from);
if (!from) return fail('from is not an email address');
let text = typeof body.text === 'string' ? body.text : '';
if (!text.trim() && typeof body.html === 'string') text = htmlToText(body.html);
text = text.replace(/\r\n/g, '\n').trim();
if (!text) return fail('message has no text');
if (text.length > MAX_TEXT) return fail(`message text is longer than ${MAX_TEXT} characters`);
const subject = typeof body.subject === 'string' ? body.subject.trim().slice(0, 300) : '';
const received = body.date ? new Date(body.date) : null;

return [
  {
    json: {
      valid: true,
      key: messageId,
      email: {
        message_id: messageId,
        from: from.email,
        from_name: from.name || null,
        subject,
        received_at: received && !Number.isNaN(received.getTime()) ? received.toISOString() : null,
        text,
      },
    },
  },
];

// Code node "Extract fields" (02 email to sheet). Run once for all items.
//
// Reads invoice fields from labelled lines of the email (no model, so the same email always
// gives the same row). Amounts in "1,234.50", "1.234,50" or "1 234,50" form are normalised; a
// slash date is accepted only when the day/month order is unambiguous. A row with a missing or
// doubtful field still reaches the sheet, but on the review tab with the reasons.
const settings = $('Settings').first().json;
const { email } = $('Validate email').first().json;
const text = `${email.subject}\n${email.text}`;

const SYMBOLS = { $: 'USD', '€': 'EUR', '£': 'GBP' };
const CURRENCIES = ['USD', 'EUR', 'GBP', 'CAD', 'AUD', 'CHF', 'SEK', 'NOK', 'DKK', 'AED'];
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const TOKEN = /[A-Za-z0-9][A-Za-z0-9/_-]*/;

function labelled(labels) {
  for (const label of labels) {
    const match = text.match(new RegExp(`(?:^|\\n)[ \\t]*(?:${label})[ \\t]*[:#-]?[ \\t]*([^\\n]+)`, 'i'));
    if (match) return match[1].trim();
  }
  return null;
}

function parseAmount(raw) {
  if (!raw) return { amount: null, currency: null };
  let currency = null;
  for (const [symbol, code] of Object.entries(SYMBOLS)) if (raw.includes(symbol)) currency = code;
  const code = raw.toUpperCase().match(new RegExp(`\\b(${CURRENCIES.join('|')})\\b`));
  if (code) currency = code[1];
  const number = raw.match(/-?\d[\d.,'  ]*/);
  if (!number) return { amount: null, currency };
  let digits = number[0].replace(/['  ]/g, '').replace(/[.,]$/, '');
  const lastComma = digits.lastIndexOf(',');
  const lastDot = digits.lastIndexOf('.');
  if (lastComma > lastDot) {
    // "1.234,50" or "1234,50": the comma is the decimal separator when two digits follow it.
    digits = /,\d{2}$/.test(digits) ? digits.replace(/\./g, '').replace(',', '.') : digits.replace(/,/g, '');
  } else {
    digits = digits.replace(/,/g, '');
  }
  const amount = Number(digits);
  return { amount: Number.isFinite(amount) ? Math.round(amount * 100) / 100 : null, currency };
}

function iso(year, month, day) {
  const date = new Date(Date.UTC(year, month - 1, day));
  const valid = date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
  return valid ? date.toISOString().slice(0, 10) : null;
}

function month(name) {
  const index = MONTHS.indexOf(name.slice(0, 3).toLowerCase());
  return index === -1 ? null : index + 1;
}

function parseDate(raw) {
  if (!raw) return { date: null, issue: null };
  let m = raw.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { date: iso(+m[1], +m[2], +m[3]), issue: null };
  m = raw.match(/(\d{1,2})\s+([A-Za-z]{3,9})\.?\s+(\d{4})/);
  if (m && month(m[2])) return { date: iso(+m[3], month(m[2]), +m[1]), issue: null };
  m = raw.match(/([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})/);
  if (m && month(m[1])) return { date: iso(+m[3], month(m[1]), +m[2]), issue: null };
  m = raw.match(/(\d{1,2})[/.](\d{1,2})[/.](\d{4})/);
  if (m) {
    const [a, b, year] = [+m[1], +m[2], +m[3]];
    if (a > 12 && b <= 12) return { date: iso(year, b, a), issue: null };
    if (b > 12 && a <= 12) return { date: iso(year, a, b), issue: null };
    if (a === b) return { date: iso(year, a, b), issue: null };
    return { date: null, issue: `due date "${m[0]}" is ambiguous (day/month order)` };
  }
  return { date: null, issue: `due date "${raw.slice(0, 40)}" not understood` };
}

const invoiceNumber = (labelled(['invoice[ \\t]*(?:number|no\\.?|#)', 'inv[ \\t]*#']) || '').match(TOKEN);
const poNumber = (labelled(['po[ \\t]*(?:number|no\\.?|#)', 'purchase[ \\t]+order']) || '').match(TOKEN);
const { amount, currency } = parseAmount(labelled(['total[ \\t]+due', 'amount[ \\t]+due', 'total', 'amount']));
const due = parseDate(labelled(['due[ \\t]+date', 'payment[ \\t]+due', 'due']));
const vendor = (labelled(['vendor', 'supplier', 'company']) || email.from_name || '').slice(0, 120) || null;

const missing = [];
const issues = [];
if (!invoiceNumber) missing.push('invoice_number');
if (amount === null) missing.push('amount');
if (!currency) missing.push('currency');
if (!due.date) missing.push('due_date');
for (const field of missing) issues.push(field === 'due_date' && due.issue ? due.issue : `${field} missing`);
const status = missing.length ? 'needs_review' : 'ok';
const tab = status === 'ok' ? settings.sheet_tab : settings.review_tab;

const row = [
  email.message_id,
  email.received_at || '',
  email.from,
  vendor || '',
  invoiceNumber ? invoiceNumber[0] : '',
  poNumber ? poNumber[0] : '',
  amount === null ? '' : amount,
  currency || '',
  due.date || '',
  status,
  issues.join('; '),
];
return [{ json: { status, tab, missing, issues, row, range: `${tab}!A1:K1` } }];

// Code node "Classify <step>" (run once for all items), right after an HTTP Request node that
// returns the full response and never throws on HTTP errors.
//
//   ok       2xx: continue
//   retry    transient (no response, 408, 429, 5xx) and attempts are left: wait, call again
//   failed   permanent (other 4xx) or attempts used up: the next node stops the run with an
//            error, so the error workflow releases the key and raises an alert
//
// Backoff: exponential with full jitter, honours Retry-After, capped at 300 s. Attempts and
// the base wait come from the Settings node, so the harness can shrink them.
const STEP = 'append';
const settings = $('Settings').first().json;
const maxAttempts = Math.max(1, Number(settings.max_attempts || 4));
const baseWaitS = Math.max(0.1, Number(settings.retry_base_s || 5));

const response = $json || {};
const status = Number(response.statusCode || 0);
const body = response.body && typeof response.body === 'object' && !Array.isArray(response.body) ? response.body : {};
const attempt = $runIndex + 1;

let route;
let transient = false;
if (status >= 200 && status < 300) {
  route = 'ok';
} else if (status === 0 || status === 408 || status === 429 || status >= 500) {
  transient = true;
  route = attempt < maxAttempts ? 'retry' : 'failed';
} else {
  route = 'failed';
}

let waitS = 0;
if (route === 'retry') {
  const headers = response.headers || {};
  const retryAfter = Number(headers['retry-after'] || 0);
  const ceiling = Math.min(300, baseWaitS * 2 ** (attempt - 1));
  const jittered = ceiling / 2 + Math.random() * (ceiling / 2);
  const chosen = Math.min(300, Math.max(jittered, Number.isFinite(retryAfter) ? retryAfter : 0));
  waitS = Math.round(chosen * 10) / 10;
}

let error = null;
if (route === 'failed') {
  const why = transient ? `gave up after ${attempt} attempts` : 'permanent error';
  const detail =
    (body.error && (body.error.message || body.error.code)) || (response.error && response.error.message) || '';
  error = `${STEP}: ${why} (HTTP ${status || 'no response'}${detail ? `: ${String(detail).slice(0, 160)}` : ''})`;
}

// Only a small, bounded copy of the answer is kept as the run's outcome.
const outcome = route === 'ok' && JSON.stringify(body).length <= 2000 ? body : route === 'ok' ? { truncated: true } : null;
return [{ json: { step: STEP, route, attempt, status_code: status, wait_s: waitS, error, outcome } }];
